
#include "gpucompose.h"
#include "gpucompose_reference.h"
#include <cassert>
#include <random>
#include <iostream>
int main(){assert(SDL_Init(0)==0);std::mt19937 rng(71288);for(int t=0;t<96;t++){int ow= t%3==0?1280:t%3==1?640:720,oh=t%3==0?720:t%3==1?360:1280;auto*a=SDL_CreateRGBSurfaceWithFormat(0,ow,oh,32,SDL_PIXELFORMAT_ARGB8888);auto*b=SDL_CreateRGBSurfaceWithFormat(0,ow,oh,32,SDL_PIXELFORMAT_ARGB8888);auto*ra=SDL_CreateSoftwareRenderer(a);auto*rb=SDL_CreateSoftwareRenderer(b);assert(a&&b&&ra&&rb);GpuCompositor candidate(ra);ReferenceGpuCompositor baseline(rb);std::vector<uint32_t>p(256*384),w(640*360);std::vector<uint8_t>flags(p.size());for(auto&v:p)v=0xFF000000|(rng()&0xFFFFFF);for(auto&v:flags){const uint8_t kinds[]={0,0x40,1,2,0x10};v=kinds[rng()%5];}for(auto&v:w)v=(rng()%3?0xFF000000u:0)|(rng()&0xFFFFFF);WideImage wide{w.data(),640,360};Scene scene;scene.wide=true;Element el=Crop(0,rng()%40,rng()%220,100+rng()%100,40+rng()%100);el.dx=(int)(rng()%100)-50;el.dy=(int)(rng()%40)-20;el.scale=0.7f+(rng()%5)*0.2f;if(t%4==0)el=FullScreen(0);scene.items={el};ScreenImage screens[2]={{p.data(),flags.data()},{p.data(),flags.data()}};candidate.Draw(scene,screens,ow,oh,t%2,&wide);baseline.Draw(scene,screens,ow,oh,t%2,&wide);std::vector<uint32_t>x(ow*oh),y(ow*oh);assert(SDL_RenderReadPixels(ra,nullptr,SDL_PIXELFORMAT_ARGB8888,x.data(),ow*4)==0);assert(SDL_RenderReadPixels(rb,nullptr,SDL_PIXELFORMAT_ARGB8888,y.data(),ow*4)==0);if(x!=y){std::cerr<<"pixel mismatch case "<<t<<'\n';return 1;}SDL_DestroyRenderer(ra);SDL_DestroyRenderer(rb);SDL_FreeSurface(a);SDL_FreeSurface(b);}SDL_Quit();std::cout<<"96 actual original/candidate frames match every pixel across crops, tall screens, portrait/landscape, mixed layer flags, alpha holes, filtering and uneven scales.\n";return 0;}
